create extension if not exists pgcrypto;
create table public.campaigns (id uuid primary key default gen_random_uuid(),slug text unique not null check(slug in ('official','test')),name text not null,get_amount integer not null check(get_amount>0),opens_at timestamptz not null,state text not null default 'scheduled' check(state in ('scheduled','open','closed','completed')),is_test boolean not null default false,created_at timestamptz not null default now());
create table public.slots (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,position smallint not null check(position between 1 and 10),month_label text not null,owner_name text,claimed_at timestamptz,unique(campaign_id,position),unique(campaign_id,month_label));
create table public.claims (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,slot_id uuid not null unique references public.slots(id) on delete cascade,claimant_name text not null,claimant_normalized text not null,request_id uuid not null,claimed_at timestamptz not null default now(),unique(campaign_id,claimant_normalized),unique(campaign_id,request_id));
create table public.audit_logs (id bigint generated always as identity primary key,campaign_id uuid references public.campaigns(id) on delete set null,slot_id uuid references public.slots(id) on delete set null,request_id uuid,claimant_name text,action text not null,result text not null,reason text,created_at timestamptz not null default now());
create table public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
insert into public.campaigns(slug,name,get_amount,opens_at,state,is_test) values ('official','WAR ARISAN CEPAT KAYA',2000000,'2026-10-02 12:00:00+07','scheduled',false),('test','WAR ARISAN CEPAT KAYA — TEST',2000000,now(),'closed',true);
insert into public.slots(campaign_id,position,month_label) select c.id,m.position,m.label from public.campaigns c cross join (values(1,'November 2026'),(2,'Desember 2026'),(3,'Januari 2027'),(4,'Februari 2027'),(5,'Maret 2027'),(6,'April 2027'),(7,'Mei 2027'),(8,'Juni 2027'),(9,'Juli 2027'),(10,'Agustus 2027')) as m(position,label);
alter table public.campaigns enable row level security; alter table public.slots enable row level security; alter table public.claims enable row level security; alter table public.audit_logs enable row level security; alter table public.admin_users enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
create policy "public reads campaigns" on public.campaigns for select using(true); create policy "public reads slots" on public.slots for select using(true); create policy "admins read claims" on public.claims for select using(public.is_admin()); create policy "admins read audit" on public.audit_logs for select using(public.is_admin()); create policy "admins read selves" on public.admin_users for select using(user_id=auth.uid()); create policy "admins update campaigns" on public.campaigns for update using(public.is_admin()) with check(public.is_admin());
create or replace function public.claim_slot(p_campaign_slug text,p_slot_id uuid,p_name text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare c public.campaigns%rowtype;s public.slots%rowtype;clean_name text:=btrim(p_name);normalized text:=lower(regexp_replace(btrim(p_name),'[[:space:]]+',' ','g'));claim_id uuid;filled integer;begin if clean_name='' or length(clean_name)>80 then return jsonb_build_object('ok',false,'code','invalid_name','message','Nama perwakilan wajib diisi (maks. 80 karakter).');end if;select * into c from public.campaigns where slug=p_campaign_slug for update;if not found then return jsonb_build_object('ok',false,'code','not_found','message','WAR tidak ditemukan.');end if;if c.state='scheduled' and not c.is_test and now()>=c.opens_at then update public.campaigns set state='open' where id=c.id; c.state:='open';end if;if c.state<>'open' then insert into public.audit_logs(campaign_id,slot_id,request_id,claimant_name,action,result,reason)values(c.id,p_slot_id,p_request_id,clean_name,'claim','failed','war_closed');return jsonb_build_object('ok',false,'code','war_closed','message','WAR belum dibuka atau telah ditutup.');end if;select * into s from public.slots where id=p_slot_id and campaign_id=c.id for update;if not found then return jsonb_build_object('ok',false,'code','invalid_slot','message','Slot tidak valid.');end if;if s.owner_name is not null then insert into public.audit_logs(campaign_id,slot_id,request_id,claimant_name,action,result,reason)values(c.id,s.id,p_request_id,clean_name,'claim','failed','slot_taken');return jsonb_build_object('ok',false,'code','slot_taken','message','Slot ini baru saja diambil orang lain.');end if;if exists(select 1 from public.claims where campaign_id=c.id and claimant_normalized=normalized) then insert into public.audit_logs(campaign_id,slot_id,request_id,claimant_name,action,result,reason)values(c.id,s.id,p_request_id,clean_name,'claim','failed','name_already_claimed');return jsonb_build_object('ok',false,'code','name_already_claimed','message','Nama ini sudah mendapatkan satu slot.');end if;insert into public.claims(campaign_id,slot_id,claimant_name,claimant_normalized,request_id) values(c.id,s.id,clean_name,normalized,p_request_id) returning id into claim_id;update public.slots set owner_name=clean_name,claimed_at=now() where id=s.id;select count(*) into filled from public.slots where campaign_id=c.id and owner_name is not null;if filled=10 then update public.campaigns set state='completed' where id=c.id;end if;insert into public.audit_logs(campaign_id,slot_id,request_id,claimant_name,action,result)values(c.id,s.id,p_request_id,clean_name,'claim','success');return jsonb_build_object('ok',true,'claim_id',claim_id,'month_label',s.month_label);exception when unique_violation then insert into public.audit_logs(campaign_id,slot_id,request_id,claimant_name,action,result,reason)values(c.id,p_slot_id,p_request_id,clean_name,'claim','failed','race_conflict');return jsonb_build_object('ok',false,'code','race_conflict','message','Slot atau nama baru saja dipakai peserta lain.');end$$;
create or replace function public.reset_test_campaign() returns jsonb language plpgsql security definer set search_path=public as $$declare c uuid;begin if not public.is_admin() then raise exception 'admin only';end if;select id into c from public.campaigns where slug='test' for update;delete from public.claims where campaign_id=c;update public.slots set owner_name=null,claimed_at=null where campaign_id=c;update public.campaigns set state='closed' where id=c;insert into public.audit_logs(campaign_id,action,result,reason)values(c,'reset','success','test reset by admin');return jsonb_build_object('ok',true,'message','Data TEST berhasil di-reset.');end$$;
grant execute on function public.claim_slot(text,uuid,text,uuid) to anon,authenticated; grant execute on function public.reset_test_campaign() to authenticated; alter publication supabase_realtime add table public.campaigns,public.slots;
